// 1. Assert Status Code & Content Type
pm.test("Status code is 200 OK", function () {
    pm.response.to.have.status(200);
});

pm.test("Content-Type is JSON", function () {
    pm.response.to.have.header("Content-Type", "application/json");
});

// 2. Validate Response Envelope Structure & Data Types
pm.test("Response contains valid envelope structure and types", function () {
    const jsonData = pm.response.json();
    
    pm.expect(jsonData).to.be.an('object');
    pm.expect(jsonData.items).to.be.an('array');
    pm.expect(jsonData.page).to.be.a('number');
    pm.expect(jsonData.limit).to.be.a('number');
    pm.expect(jsonData.total).to.be.a('number');
});

// 3. Dynamic Schema Validation for Array Items
pm.test("Each listing item has valid properties and schema types", function () {
    const jsonData = pm.response.json();
    
    jsonData.items.forEach(function(item) {
        pm.expect(item.id).to.be.a('string');
        pm.expect(item.title).to.be.a('string');
        pm.expect(item.location).to.be.a('string');
        pm.expect(item.category).to.be.a('string');
        pm.expect(item.url).to.be.a('string');
        
        // Price and Condition can be null or specific types according to contract
        if (item.price !== null) {
            pm.expect(item.price).to.be.a('number');
        }
        if (item.condition !== null) {
            pm.expect(item.condition).to.be.a('string');
        }
    });
});

